    SRGRetrievalStatus.add(RESOURCE_URL: RESOURCE_URL, &fbb)
    SRGRetrievalStatus.add(BYTE_LENGTH: BYTE_LENGTH, &fbb)
    SRGRetrievalStatus.add(SHA256: SHA256, &fbb)
    SRGRetrievalStatus.add(SCANNED_COUNT: SCANNED_COUNT, &fbb)
    SRGRetrievalStatus.add(SUPPORTED_COUNT: SUPPORTED_COUNT, &fbb)
    SRGRetrievalStatus.add(NEXT_OFFSET: NEXT_OFFSET, &fbb)
    SRGRetrievalStatus.add(NOTE: NOTE, &fbb)
    return SRGRetrievalStatus.endSRGRetrievalStatus(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
