///  Data Source Registry - providers, their resources, storage receipts and
///  retrieval progress.
public struct SRG: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$SRG" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: SRG.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let REGISTRY_ID: VOffset = 4
    static let UPSTREAM_REPOSITORY: VOffset = 6
    static let UPSTREAM_REVISION: VOffset = 8
    static let REGISTRY_PATH: VOffset = 10
    static let GENERATED_AT_MS: VOffset = 12
    static let PROVIDERS: VOffset = 14
    static let RESOURCES: VOffset = 16
    static let RECEIPTS: VOffset = 18
    static let STATUS: VOffset = 20
    static let SETTINGS: VOffset = 22
  }

  ///  Identifier of the registry, e.g. a repository name or a node's registry
  ///  name; empty = not named.
  public var REGISTRY_ID: String? { let o = _accessor.offset(VT.REGISTRY_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var REGISTRY_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.REGISTRY_ID) }
  ///  Where the registry's provider list comes from, when it mirrors an
  ///  upstream list: the repository URL, the revision mirrored and the path of
  ///  the list inside it.
  public var UPSTREAM_REPOSITORY: String? { let o = _accessor.offset(VT.UPSTREAM_REPOSITORY); return o == 0 ? nil : _accessor.string(at: o) }
  public var UPSTREAM_REPOSITORYSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.UPSTREAM_REPOSITORY) }
  public var UPSTREAM_REVISION: String? { let o = _accessor.offset(VT.UPSTREAM_REVISION); return o == 0 ? nil : _accessor.string(at: o) }
  public var UPSTREAM_REVISIONSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.UPSTREAM_REVISION) }
  public var REGISTRY_PATH: String? { let o = _accessor.offset(VT.REGISTRY_PATH); return o == 0 ? nil : _accessor.string(at: o) }
  public var REGISTRY_PATHSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.REGISTRY_PATH) }
  ///  Unix milliseconds this record was generated (for a discovery queue, the
  ///  time of discovery); 0 = not stated.
  public var GENERATED_AT_MS: Int64 { let o = _accessor.offset(VT.GENERATED_AT_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  public var PROVIDERS: FlatbufferVector<SRGProvider> { return _accessor.vector(at: VT.PROVIDERS, byteSize: 4) }
  ///  Resources, in retrieval order. A single job carries one.
  public var RESOURCES: FlatbufferVector<SRGResource> { return _accessor.vector(at: VT.RESOURCES, byteSize: 4) }
  public var RECEIPTS: FlatbufferVector<SRGContentReceipt> { return _accessor.vector(at: VT.RECEIPTS, byteSize: 4) }
  public var STATUS: SRGRetrievalStatus? { let o = _accessor.offset(VT.STATUS); return o == 0 ? nil : SRGRetrievalStatus(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var SETTINGS: SRGRetrievalSettings? { let o = _accessor.offset(VT.SETTINGS); return o == 0 ? nil : SRGRetrievalSettings(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startSRG(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 10) }
  public static func add(REGISTRY_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REGISTRY_ID, at: VT.REGISTRY_ID) }
  public static func add(UPSTREAM_REPOSITORY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: UPSTREAM_REPOSITORY, at: VT.UPSTREAM_REPOSITORY) }
  public static func add(UPSTREAM_REVISION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: UPSTREAM_REVISION, at: VT.UPSTREAM_REVISION) }
  public static func add(REGISTRY_PATH: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REGISTRY_PATH, at: VT.REGISTRY_PATH) }
  public static func add(GENERATED_AT_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: GENERATED_AT_MS, def: 0, at: VT.GENERATED_AT_MS) }
  public static func addVectorOf(PROVIDERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROVIDERS, at: VT.PROVIDERS) }
  public static func addVectorOf(RESOURCES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RESOURCES, at: VT.RESOURCES) }
  public static func addVectorOf(RECEIPTS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RECEIPTS, at: VT.RECEIPTS) }
  public static func add(STATUS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATUS, at: VT.STATUS) }
  public static func add(SETTINGS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SETTINGS, at: VT.SETTINGS) }
  public static func endSRG(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createSRG(
    _ fbb: inout FlatBufferBuilder,
    REGISTRY_IDOffset REGISTRY_ID: Offset = Offset(),
    UPSTREAM_REPOSITORYOffset UPSTREAM_REPOSITORY: Offset = Offset(),
    UPSTREAM_REVISIONOffset UPSTREAM_REVISION: Offset = Offset(),
    REGISTRY_PATHOffset REGISTRY_PATH: Offset = Offset(),
    GENERATED_AT_MS: Int64 = 0,
    PROVIDERSVectorOffset PROVIDERS: Offset = Offset(),
    RESOURCESVectorOffset RESOURCES: Offset = Offset(),
    RECEIPTSVectorOffset RECEIPTS: Offset = Offset(),
    STATUSOffset STATUS: Offset = Offset(),
    SETTINGSOffset SETTINGS: Offset = Offset()
  ) -> Offset {
    let __start = SRG.startSRG(&fbb)
    SRG.add(REGISTRY_ID: REGISTRY_ID, &fbb)
    SRG.add(UPSTREAM_REPOSITORY: UPSTREAM_REPOSITORY, &fbb)
    SRG.add(UPSTREAM_REVISION: UPSTREAM_REVISION, &fbb)
    SRG.add(REGISTRY_PATH: REGISTRY_PATH, &fbb)
    SRG.add(GENERATED_AT_MS: GENERATED_AT_MS, &fbb)
    SRG.addVectorOf(PROVIDERS: PROVIDERS, &fbb)
    SRG.addVectorOf(RESOURCES: RESOURCES, &fbb)
    SRG.addVectorOf(RECEIPTS: RECEIPTS, &fbb)
    SRG.add(STATUS: STATUS, &fbb)
    SRG.add(SETTINGS: SETTINGS, &fbb)
    return SRG.endSRG(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.REGISTRY_ID, fieldName: "REGISTRY_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.UPSTREAM_REPOSITORY, fieldName: "UPSTREAM_REPOSITORY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.UPSTREAM_REVISION, fieldName: "UPSTREAM_REVISION", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.REGISTRY_PATH, fieldName: "REGISTRY_PATH", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.GENERATED_AT_MS, fieldName: "GENERATED_AT_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PROVIDERS, fieldName: "PROVIDERS", required: false, type: ForwardOffset<Vector<ForwardOffset<SRGProvider>, SRGProvider>>.self)
    try _v.visit(field: VT.RESOURCES, fieldName: "RESOURCES", required: false, type: ForwardOffset<Vector<ForwardOffset<SRGResource>, SRGResource>>.self)
    try _v.visit(field: VT.RECEIPTS, fieldName: "RECEIPTS", required: false, type: ForwardOffset<Vector<ForwardOffset<SRGContentReceipt>, SRGContentReceipt>>.self)
    try _v.visit(field: VT.STATUS, fieldName: "STATUS", required: false, type: ForwardOffset<SRGRetrievalStatus>.self)
    try _v.visit(field: VT.SETTINGS, fieldName: "SETTINGS", required: false, type: ForwardOffset<SRGRetrievalSettings>.self)
    _v.finish()
  }
}
